{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name IN ('POST','POST /api/v1/preserveservice/preserve') GROUP BY ALL ORDER BY 1,3",
          "claim": "Preserve's outgoing POST calls fail in about 4 ms with Error status; 284 of them, while its inbound preserve endpoint returns 500."
        },
        {
          "kind": "log",
          "sql": "SELECT message, count(*) c FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' GROUP BY message ORDER BY c DESC LIMIT 5",
          "claim": "Preserve logs SEVERE exceptions: I/O error on POST to ts-basic-service /basic/travel, 'Unexpected end of file from server'."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code code, attr_status_code, count(*) n, round(avg(duration)/1e6,1) ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name LIKE '%travel%' GROUP BY ALL ORDER BY 2,3",
          "claim": "Basic-service's own /travel server spans still return 200 at normal self-time, so the failure is not inside basic-service."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_http_response_status_code code, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%preserve%' GROUP BY ALL",
          "claim": "Dashboard's preserve requests return HTTP 500 (14 errors) with p95 rising from about 1.5 s to about 18.6 s."
        }
      ]
    }
  ]
}
